module "fn_source_bucket" {
  source             = "git::ssh://git@github.com/liftitapp/tf-modules.git//cloud-storage"
  bucket_name        = "${local.project_id[terraform.workspace]}-restore-fn-source"
  location           = local.region.principal
  versioning_enabled = false
}

data "archive_file" "vm_validator" {
  type        = "zip"
  source_dir  = "${path.module}/functions/vm-validator"
  output_path = "${path.module}/functions/vm-validator.zip"
}

resource "google_storage_bucket_object" "vm_validator_source" {
  name   = "vm-validator-${data.archive_file.vm_validator.output_md5}.zip"
  bucket = module.fn_source_bucket.bucket_name
  source = data.archive_file.vm_validator.output_path
}

resource "google_cloudfunctions2_function" "vm_validator" {
  name        = "restore-test-vm-validator"
  description = "Validates VM services after restore from snapshot"
  project     = local.project_id[terraform.workspace]
  location    = local.region.principal

  labels = local.default_labels

  build_config {
    runtime     = "python312"
    entry_point = "validate_vm"

    source {
      storage_source {
        bucket = module.fn_source_bucket.bucket_name
        object = google_storage_bucket_object.vm_validator_source.name
      }
    }
  }

  service_config {
    max_instance_count    = 1
    min_instance_count    = 0
    available_memory      = "256M"
    timeout_seconds       = 300
    service_account_email = module.sa-permissions.service_account_email

    environment_variables = {
      PROJECT_ID = local.project_id[terraform.workspace]
    }

    ingress_settings               = "ALLOW_INTERNAL_ONLY"
    all_traffic_on_latest_revision = true

    vpc_connector                 = local.has_vpc_connector ? "projects/${local.vpc_connector_project}/locations/${local.region.principal}/connectors/serverless-connector" : null
    vpc_connector_egress_settings = local.has_vpc_connector ? "PRIVATE_RANGES_ONLY" : null
  }
}

#-----------------------------------------
# IAM binding to allow workflow to invoke Cloud Function Gen2
# Cloud Functions Gen2 uses Cloud Run under the hood, so we need
# roles/run.invoker on the underlying Cloud Run service
#-----------------------------------------
resource "google_cloud_run_service_iam_member" "vm_validator_invoker" {
  location = local.region.principal
  project  = local.project_id[terraform.workspace]
  service  = google_cloudfunctions2_function.vm_validator.name
  role     = "roles/run.invoker"
  member   = "serviceAccount:${module.sa-permissions.service_account_email}"
}

