content.content:
resource "google_storage_bucket" "audit_logs" {
  name     = local.audit_bucket_name
  location = local.region.principal
  project  = local.project_id["sec"]

  storage_class               = "COLDLINE"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key_name = google_kms_crypto_key.audit_logs.id
  }

  retention_policy {
    retention_period = local.audit_retention_seconds
    is_locked        = true # IRREVERSIBLE — activado 2026-04-29 tras validar sink end-to-end
  }

  lifecycle_rule {
    action {
      type          = "SetStorageClass"
      storage_class = "ARCHIVE"
    }
    condition {
      age = local.audit_lifecycle_archive_days
    }
  }

  labels = local.default_labels

  depends_on = [google_kms_crypto_key_iam_member.audit_logs_gcs]
}

